import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { describe, it } from "node:test";
import { normalizeName, parseRequirement, PEP440 } from "../../src/pep440.ts";

// Generated by scripts/pep440-oracle.py with Python's `packaging`, the reference implementation.
const oracle = JSON.parse(readFileSync(new URL("../fixtures/pep440-oracle.json", import.meta.url), "utf8")) as {
  cmp: Array<[string, string, number]>;
  sat: Array<[string, string, boolean]>;
};

describe("PEP 440", () => {
  it("orders versions exactly like packaging.version", () => {
    for (const [a, b, want] of oracle.cmp) assert.equal(Math.sign(PEP440.compare(a, b)), want, `${a} vs ${b}`);
  });

  it("matches specifier sets exactly like packaging.specifiers (pre-releases included)", () => {
    for (const [v, s, want] of oracle.sat) assert.equal(PEP440.satisfies(v, s), want, `${v} in "${s}"`);
  });

  it("parses PEP 508 requirements and normalizes names", () => {
    assert.deepEqual(parseRequirement('Jinja2[i18n] (>=2.10,<3); python_version >= "3.8"'), {
      name: "jinja2",
      extras: ["i18n"],
      specifier: ">=2.10,<3",
      marker: 'python_version >= "3.8"',
    });
    assert.deepEqual(parseRequirement("tar_lite==3.1.4"), { name: "tar-lite", extras: [], specifier: "==3.1.4" });
    assert.equal(parseRequirement("pkg @ https://example.com/pkg.whl"), null);
    assert.equal(normalizeName("Tar.Lite__x"), "tar-lite-x");
  });

  it("writes OSV intervals and compatible lines in PEP 440 terms", () => {
    assert.equal(PEP440.interval({ gte: "3.0.0", lt: "3.1.4" }), ">=3.0.0,<3.1.4");
    assert.equal(PEP440.exact("3.2.0"), "==3.2.0");
    assert.equal(PEP440.compatibleLine("3.2.0"), "3");
    assert.equal(PEP440.compatibleLine("0.4.1"), "0.4");
  });
});
